INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Seated_Palms-Down_Barbell_Wrist_Curl', 'Seated Palms-Down Barbell Wrist Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your forearms on top of your upper thighs with your palms down. Tip: Make sure that the back of the wrists lay on top of your knees. This will be your starting position. Lower the bar as far as possible while inhaling and keeping a tight grip. Now curl bar up as high as possible whil'),
('Seated_Side_Lateral_Raise', 'Seated Side Lateral Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Pick a couple of dumbbells and sit at the end of a flat bench with your feet firmly on the floor. Hold the dumbbells with your palms facing in and your arms straight down at your sides at arms'' length. This will be your starting position. While maintaining the torso stationary (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as yo'),
('Seated_Triceps_Press', 'Seated Triceps Press', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm''s length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular mot'),
('Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl', 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it. Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up. Now hold the handle with both hands, palms up, using a shoulder-width grip. Step back and sit on the bench with your feet about shoulder width apart, firmly on the floor. Lean forward and place the forearms on your thighs with the back of your '),
('See-Saw_Press_Alternating_Side_Press', 'See-Saw Press (Alternating Side Press)', 'shoulders', ARRAY['core','arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Grab a dumbbell with each hand and stand up erect. Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position. Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up. Your elbows should come out also as you lift the weight. Simultaneously, you will also be bending from yo'),
('Shotgun_Row', 'Shotgun Row', 'back', ARRAY['arms','back']::text[], 'cable', 'strength', 'beginner', 'Attach a single handle to a low cable. After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position. Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go. After a brief pause, return to the starting position.'),
('Shoulder_Circles', 'Shoulder Circles', 'shoulders', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'With shoulders relaxed and arms resting loosely at your sides (or in your lap if you''re seated), gently roll your shoulders forward, up, back, and down. Reverse direction. You can do this exercise alternating shoulders or both at the same time.'),
('Shoulder_Press_-_With_Bands', 'Shoulder Press - With Bands', 'shoulders', ARRAY['arms']::text[], 'bands', 'strength', 'beginner', 'To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles and lift them so that the hands are at shoulder height at each side. Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position. As you exhale, lift the handles up until your arms are fully extended overhead.'),
('Shoulder_Raise', 'Shoulder Raise', 'shoulders', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Relax your arms to your sides and raise your shoulders up toward your ears, then back down.'),
('Shoulder_Stretch', 'Shoulder Stretch', 'shoulders', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Reach your left arm across your body and hold it straight.'),
('Side-Lying_Floor_Stretch', 'Side-Lying Floor Stretch', 'back', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'First lie on your left side, bending your left knee in front of you to stabilize your torso (use your abdominal muscles as well to hold you upright). Straighten your right leg and rest the right foot on the floor behind your left. Straighten your right arm over your head and gently pull on your right wrist to stretch the entire right side of the body. Switch sides.'),
('Side_Bridge', 'Side Bridge', 'core', ARRAY['shoulders']::text[], 'bodyweight', 'strength', 'beginner', NULL),
('Side_Hop-Sprint', 'Side Hop-Sprint', 'legs', ARRAY['legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Stand to the side of a cone or hurdle. Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started. Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop.'),
('Side_Jackknife', 'Side Jackknife', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', NULL),
('Side_Lateral_Raise', 'Side Lateral Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position. While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a secon'),
('Side_Laterals_to_Front_Raise', 'Side Laterals to Front Raise', 'shoulders', ARRAY['back']::text[], 'dumbbell', 'strength', 'beginner', 'In a standing position, hold a pair of dumbbells at your side. This will be your starting position. Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating. At the top of the exercise move the weights out in front of you, keeping your arms extended. Lower the weights with a controlled motion. On the next repetition, raise the weights in front of you to shoulder height before moving the weights laterally to your sides. Lo'),
('Side_Leg_Raises', 'Side Leg Raises', 'legs', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'Stand next to a chair, which you may hold onto as a support. Stand on one leg. This will be your starting position. Keeping your leg straight, raise it as far out to the side as possible, and swing it back down, allowing it to cross the opposite leg. Repeat this swinging motion 5-10 times, increasing the range of motion as you do so.'),
('Side_Lying_Groin_Stretch', 'Side Lying Groin Stretch', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Start off by lying on your right side and bend your right knee in front of you to stabilize the torso. Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder). Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides.'),
('Side_Neck_Stretch', 'Side Neck Stretch', 'other', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Start with your shoulders relaxed, gently tilt your head towards your shoulder. Assist stretch with a gentle pull on the side of the head.'),
('Side_Standing_Long_Jump', 'Side Standing Long Jump', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position. Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can. Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body.'),
('Side_To_Side_Chins', 'Side To Side Chins', 'back', ARRAY['arms','arms','back','shoulders']::text[], 'other', 'strength', 'intermediate', 'Grab the pull-up bar with the palms facing forward using a wide grip. As you have both arms extended in front of you holding the bar at a wide grip, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position. Pull your torso up while leaning to the left hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of '),
('Side_Wrist_Pull', 'Side Wrist Pull', 'shoulders', ARRAY['arms','back']::text[], 'other', 'stretching', 'beginner', 'This stretch works best standing. Cross your left arm over the midline of your body and hold the left wrist in your right hand down at the level of your hips. Start the stretch with a bent left arm. Slowly straighten, pull, and lift it up to shoulder height, as pictured. Feel this stretch originate in your back, not your shoulders, and don''t pull too hard on the shoulders joint. Switch sides.'),
('Side_to_Side_Box_Shuffle', 'Side to Side Box Shuffle', 'legs', ARRAY['legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Stand to one side of the box with your left foot resting on the middle of it. To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement. Continue shuffling back and forth across the box.'),
('Single-Arm_Cable_Crossover', 'Single-Arm Cable Crossover', 'chest', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand. Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position. Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be per'),
('Single-Arm_Linear_Jammer', 'Single-Arm Linear Jammer', 'shoulders', ARRAY['chest','arms']::text[], 'barbell', 'strength', 'intermediate', 'Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight. Raise the bar from the floor, taking it to your shoulders with one or both hands. Adopt a wide stance. This will be your starting position. Perform the movement by extending the elbow, pressing the weight up. Move explosively, extending the hips and knees fully to produce maximal force. Return to the starting position.'),
('Single-Arm_Push-Up', 'Single-Arm Push-Up', 'chest', ARRAY['shoulders','arms']::text[], 'bodyweight', 'strength', 'intermediate', 'Begin laying prone on the ground. Move yourself into a position supporting your weight on your toes and one arm. Your working arm should be placed directly under the shoulder, fully extended. Your legs should be extended, and for this movement you may need a wider base, placing your feet further apart than in a normal push-up. Maintain good posture, and place your free hand behind your back. This will be your starting position. Lower yourself by allowing the elbow to flex until you touch the gro'),
('Single-Cone_Sprint_Drill', 'Single-Cone Sprint Drill', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward. Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your knees up, with violent foot action. Rest after three trips around the cone.'),
('Single-Leg_High_Box_Squat', 'Single-Leg High Box Squat', 'legs', ARRAY['legs','legs']::text[], 'other', 'strength', 'beginner', 'Position a box in a rack. Secure a band or rope in place above the box. Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance . Continue stepping up and down on the same leg before switching to the opposite side.'),
('Single-Leg_Hop_Progression', 'Single-Leg Hop Progression', 'legs', ARRAY['legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Arrange a line of cones in front of you. Assume a relaxed standing position, balanced on one leg. Raise the knee of your opposite leg. This will be your starting position. Hop forward, jumping and landing with the same leg over the cone. Use a countermovement jump to hop from cone to cone. At the end, turn around and go back on the other leg.'),
('Single-Leg_Lateral_Hop', 'Single-Leg Lateral Hop', 'legs', ARRAY['legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your knee slightly bent. To begin, execute a counterjump to hop sideways over the cone. Land on your jumping leg, and immediately rebound out of it by jumping back to the start position. Continue hopping back and forth.'),
('Single-Leg_Leg_Extension', 'Single-Leg Leg Extension', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Seat yourself in the machine and adjust it so that you are positioned properly. The pad should be against the lower part of the shin but not in contact with the ankle. Adjust the seat so that the pivot point is in line with your knee. Select a weight appropriate for your abilities. Maintaining good posture, fully extend one leg, pausing at the top of the motion. Return to the starting position without letting the weight stop, keeping tension on the muscle. Repeat for the desired number of repeti'),
('Single-Leg_Stride_Jump', 'Single-Leg Stride Jump', 'legs', ARRAY['legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Stand to the side of a box with your inside foot on top of it, close to the edge. Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward. Land in the same position that you started, using your inside leg to decelerate the impact.'),
('Single_Dumbbell_Raise', 'Single Dumbbell Raise', 'shoulders', ARRAY['arms','back']::text[], 'dumbbell', 'strength', 'beginner', 'With a wide stance, hold a dumbell with both hands, grasping the head of the dumbbell instead of the handle. Your arms should be extended and hanging at the waist. This will be your starting position. Raise the weight until it is above shoulder level, keeping your arms extended. Your torso and hips should remain stationary throughout the movement. Return to the starting position and repeat for the recommended amount of repetitions.'),
('Single_Leg_Butt_Kick', 'Single Leg Butt Kick', 'legs', ARRAY['legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Begin by standing on one leg, with the bent knee raised. This will be your start position. Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg. Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg. Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill.'),
('Single_Leg_Glute_Bridge', 'Single Leg Glute Bridge', 'legs', ARRAY['legs']::text[], 'bodyweight', 'strength', 'beginner', 'Lay on the floor with your feet flat and knees bent. Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position. Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground. Extend as far as possible, pause and then return to the starting position.'),
('Single_Leg_Push-off', 'Single Leg Push-off', 'legs', ARRAY['legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Stand on the ground with one foot resting on the box, heel close to the edge. Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and knee. Land with the same foot on top of the box, returning your other foot back to the start position.'),
('Sit-Up', 'Sit-Up', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees. Place your hands behind your head and lock them together by clasping your fingers. This is the starting position. Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise. Once you feel the contraction for a second, lower your upper body back down to the starting po'),
('Sit_Squats', 'Sit Squats', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'stretching', 'beginner', 'Stand with your feet shoulder width apart. This will be your starting position. Begin the movement by flexing your knees and hips, sitting back with your hips. Continue until you have squatted a portion of the way down, but are above parallel, and quickly reverse the motion until you return to the starting position. Repeat for 5-10 repetitions.'),
('Skating', 'Skating', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'cardio', 'intermediate', 'Roller skating is a fun activity which can be effective in improving cardiorespiratory fitness and muscular endurance. It requires relatively good balance and coordination. It is necessary to learn the basics of skating including turning and stopping and to wear protective gear to avoid possible injury. You can skate at a comfortable pace for 30 minutes straight. If you want a cardio challenge, do interval skating — speed skate two minutes of every five minutes, using the remaining three minutes'),
('Sled_Drag_-_Harness', 'Sled Drag - Harness', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'strongman', 'beginner', 'To begin, load the sled with the desired weight and attach the pulling strap. You can pull with handles, use a harness, or attach the pulling strap to a weight belt. Whether pulling forwards or backwards, lean in the direction of travel and progress by extending through the hips and knees.'),
('Sled_Overhead_Backward_Walk', 'Sled Overhead Backward Walk', 'shoulders', ARRAY['legs','back','legs']::text[], 'other', 'strength', 'beginner', 'Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight. Face the sled, backing up until there is some tension in the line. Hold your hands directly above your head with your elbows extended. This will be your starting position. Walk backwards, keeping your arms raised above your head. Avoid jerky movements.'),
('Sled_Overhead_Triceps_Extension', 'Sled Overhead Triceps Extension', 'arms', ARRAY[]::text[], 'other', 'strength', 'beginner', 'Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load. Facing away from the sled, step away until there is tension in the line. Raise your hands above your head, keeping them together, palms facing each other. Your elbows should be pointed upward with the elbows flexed. This will be your starting position. Extend through the elbow to straighten the arm. Ensure that your upper arm stays in position to isolate the triceps. Upon full extension, step forward to ta'),
('Sled_Push', 'Sled Push', 'legs', ARRAY['legs','chest','legs','legs','arms']::text[], 'other', 'strongman', 'beginner', 'Load your pushing sled with the desired weight. Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles. Push the sled as fast as possible, focusing on extending your hips and knees to strengthen your posterior chain.'),
('Sled_Reverse_Flye', 'Sled Reverse Flye', 'shoulders', ARRAY[]::text[], 'other', 'strength', 'beginner', 'Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight. Face the sled, backing up until there is some tension in the line. Take both handles at arms length at about waist level. Bend the knees slightly and keep your chest and head up. This will be your starting position. Without flexing the elbow, pull the handles upward and apart, performing a reverse fly with some external rotation. Your palms should be facing forward as you do this. Return to the starting '),
('Sled_Row', 'Sled Row', 'back', ARRAY['arms','back']::text[], 'other', 'strength', 'beginner', 'Attach dual handles to a sled connected by a rope or chain. Load the sled to an appropriate weight. Face the sled, backing up until there is some tension in the line. With a handle in each hand, bend the knees slightly, keep your head and chest up, and begin with your arms extended. To initiate the movement, flex the elbow as you retract your shoulder blades, pulling the sled towards you. Take a step or two back to get tension in the line and repeat.'),
('Sledgehammer_Swings', 'Sledgehammer Swings', 'core', ARRAY['legs','arms','back','back','shoulders']::text[], 'other', 'plyometrics', 'beginner', 'You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer. If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head. As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Contr'),
('Smith_Incline_Shoulder_Raise', 'Smith Incline Shoulder Raise', 'shoulders', ARRAY['chest']::text[], 'barbell', 'strength', 'beginner', 'Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your shoulders are aligned right under the barbell. Using a shoulder width pronated (palms forward) grip, lift the bar from the rack and hold it straight over you with a slight bend at the elbows. This will be your starting position. As you breathe out, lift '),
('Smith_Machine_Behind_the_Back_Shrug', 'Smith Machine Behind the Back Shrug', 'back', ARRAY['shoulders']::text[], 'machine', 'strength', 'beginner', 'With the bar at thigh level, load an appropriate weight. Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position. Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement. After a brief pause return the weight to the starting position. Repeat for the desired number of repe'),
('Smith_Machine_Bench_Press', 'Smith Machine Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest. After a second pau'),
('Smith_Machine_Bent_Over_Row', 'Smith Machine Bent Over Row', 'back', ARRAY['arms','back','shoulders']::text[], 'machine', 'strength', 'beginner', 'Set the barbell attached to the smith machine to a height that is about 2 inches below your knees. Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your t')
